    },
    {
      "company": "TechDispatch",
      "type": "direct",
      "severity": "blocking",
      "rationale": "TechDispatch is an HVAC/Plumbing Scheduling SaaS. Cadence explicitly targets SMB service businesses including trades like HVAC/plumbing, and its core product (scheduling and dispatch) is functionally identical to TechDispatch's offering in that vertical."
    },
